package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewTokenBucketValidation(t *testing.T) {
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 2, newFakeClock(), false},
		{"nil clock ok", 10, 2, nil, false},
		{"zero capacity", 0, 2, newFakeClock(), true},
		{"negative capacity", -1, 2, newFakeClock(), true},
		{"zero rate", 10, 0, newFakeClock(), true},
		{"negative rate", 10, -1, newFakeClock(), true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := NewTokenBucket(tt.capacity, tt.rate, tt.clock)
			if tt.wantErr && err == nil {
				t.Fatal("expected error")
			}
			if !tt.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

