	tests := []struct {
		name   string
		advance time.Duration
		n      int
		want   bool
	}{
		{"consume one", 0, 1, true},
		{"consume all", 0, 5, true},
		{"over capacity", 0, 6, false},
		{"refill after advance", time.Second, 1, true},
		{"negative n", 0, -1, false},
		{"zero n", 0, 0, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := NewTokenBucket(5, 1, clock)
			if err != nil {
				t.Fatal(err)
			}
