				clock.Advance(tt.advance)
			}
			if got := b.AllowN(tt.n); got != tt.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestRefillCapsAtCapacity(t *testing.T) {
	clock := newFakeClock()
	b, err := NewTokenBucket(2, 10, clock)
	if err != nil {
		t.Fatal(err)
	}
	clock.Advance(time.Hour)
	if got := b.Tokens(); got != 2 {
		t.Fatalf("Tokens() = %v, want 2", got)
	}
}

func TestConcurrentAllow(t *testing.T) {
	clock := newFakeClock()
	b, err := NewTokenBucket(100, 1000, clock)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	allowed := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			allowed <- b.Allow()
		}()
	}
	wg.Wait()
	close(allowed)
	count := 0
	for ok := range allowed {
		if ok {
			count++
		}
	}
	if count != 100 {
		t.Fatalf("allowed = %d, want 100", count)
	}
