package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock supplies the current time. Inject a fake in tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New creates a full bucket. capacity must be > 0 and ratePerSecond > 0.
func New(capacity int, ratePerSecond float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if ratePerSecond <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     ratePerSecond,
		last:     now,
		clock:    clock,
	}, nil
}

// NewReal returns a bucket using the system clock.
func NewReal(capacity int, ratePerSecond float64) (*TokenBucket, error) {
	return New(capacity, ratePerSecond, realClock{})
}

// Allow reports whether one token is available.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// AllowN reports whether n tokens are available and consumes them if so.
// n == 0 always succeeds; n < 0 always fails.
func (b *TokenBucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if float64(n) > b.tokens {
		return false
	}
	b.tokens -= float64(n)
	return true
}

// Tokens returns the current estimated token count.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	return b.tokens
}

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}
