package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.t
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.t = f.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 5, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 5, 0, clk, true},
		{"negative rate", 5, -1, clk, true},
		{"valid", 5, 1, clk, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.capacity, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	cases := []struct {
		name   string
		cap    int
		rate   float64
		advance time.Duration
		n      int
		want   bool
	}{
		{"initial burst", 5, 10, 0, 5, true},
		{"exceeds burst", 5, 10, 0, 6, false},
		{"refill after advance", 5, 10, 200 * time.Millisecond, 2, true},
		{"refill capped at capacity", 5, 10, time.Hour, 5, true},
		{"zero n", 5, 10, 0, 0, true},
		{"negative n", 5, 10, 0, -1, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clk := &fakeClock{t: time.Unix(0, 0)}
			b, err := New(tc.cap, tc.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			clk.Advance(tc.advance)
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	b, err := New(100, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if allowed.Load() != 100 {
		t.Fatalf("allowed = %d, want 100", allowed.Load())
	}
}
